export function FilePicker({
  label = "{{label}}",
  chosenFile = "{{chosenFile}}",
  accept = "{{accept}}",
  multiple = {{multiple}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 280, padding: 16, borderRadius: 10, boxSizing: "border-box", border: "1px solid #24143018" }}>
      <label style={{ position: "relative", display: "inline-block", padding: "8px 16px", borderRadius: 8, fontWeight: 700, color: "#14351f", cursor: "pointer", background: accent }}>
        {label}
        <input type="file" multiple={multiple} style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)", whiteSpace: "nowrap" }} />
      </label>
      <p style={{ margin: "10px 0 2px", fontWeight: 600 }}>{chosenFile}</p>
      <p style={{ margin: 0, fontSize: 11, color: "#24143088" }}>Accepted: <span style={{ fontWeight: 700, textTransform: "capitalize" }}>{accept}</span></p>
    </div>
  );
}
